interface Logger {
  log(message: string): void
}
class ConsoleLogger implements Logger {
  log(message: string) { console.log(message) }
}
class NullLogger implements Logger {
  log(_message: string) { /* no-op */ }
}
// Client always calls logger.log without null checks
const logger: Logger = new NullLogger()
logger.log('started')

interface Notifier { notify(msg: string): void }
class EmailNotifier implements Notifier { notify(msg: string) { /* send email */ } }
class Service {
  notifier?: Notifier
  sendReport(data: any) {
    if (this.notifier) { this.notifier.notify('report ready') }
  }
}

// Version A
interface Logger { log(msg: string): void }
class NoopLogger implements Logger { log(_msg: string) { /* no-op */ } }
class AppA { constructor(public logger: Logger = new NoopLogger()) {} doWork() { this.logger.log('work') } }

// Version B
class AppB { constructor(public logger?: Logger) {} doWork() { if (this.logger) { this.logger.log('work') } } }
